import{_ as i,o,c as t,a0 as a}from"./chunks/framework.Bmhw_dvp.js";const f=JSON.parse('{"title":"Notifications","description":"PubSub logic for the notification inbox and background tasks.","frontmatter":{"isInternal":true,"type":"Specification","title":"Notifications","description":"PubSub logic for the notification inbox and background tasks.","tags":["features","specs","architecture"]},"headers":[],"relativePath":"specs/features/notifications.md","filePath":"specs/features/notifications.md"}'),n={name:"specs/features/notifications.md"};function r(c,e,s,l,d,u){return o(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="notifications-technical-specification" tabindex="-1">Notifications Technical Specification <a class="header-anchor" href="#notifications-technical-specification" aria-label="Permalink to &quot;Notifications Technical Specification&quot;">​</a></h1><h2 id="_1-overview" tabindex="-1">1. Overview <a class="header-anchor" href="#_1-overview" aria-label="Permalink to &quot;1. Overview&quot;">​</a></h2><p>The Notification System provides an asynchronous inbox for long-running tasks, allowing users to leave the page while a render or upload is occurring.</p><h2 id="_2-architecture" tabindex="-1">2. Architecture <a class="header-anchor" href="#_2-architecture" aria-label="Permalink to &quot;2. Architecture&quot;">​</a></h2><ul><li><strong>Collection</strong>: <code>users/{userId}/notifications/{notificationId}</code></li><li><strong>Fields</strong>: <code>title</code>, <code>message</code>, <code>type</code> (success/error/info), <code>read</code> (boolean), <code>link</code> (optional deep link), <code>createdAt</code>.</li></ul><h2 id="_3-trigger-mechanisms" tabindex="-1">3. Trigger Mechanisms <a class="header-anchor" href="#_3-trigger-mechanisms" aria-label="Permalink to &quot;3. Trigger Mechanisms&quot;">​</a></h2><ul><li><strong>Cloud Functions</strong>: When a background task (like FFmpeg render or YouTube upload) completes, the Cloud Function writes a document to the user&#39;s notifications subcollection.</li><li><strong>Real-Time Delivery</strong>: The frontend UI (specifically the <code>NavBar</code> badge) subscribes to <code>onSnapshot</code> queries where <code>read == false</code>.</li><li><strong>Error Handling</strong>: If a render fails due to timeout or OOM, the Cloud Function catches the error and writes a high-priority error notification so the user isn&#39;t left hanging.</li></ul>',7)])])}const g=i(n,[["render",r]]);export{f as __pageData,g as default};
